SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十二", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/jiuwudaishi-082-944-january/source.txt", "note": "《旧五代史》卷八十二，段落 jiu-wudaishi-205deb4a7860-p001999；EPUB电子本，纸本及异文待核", "id": "fbcc6d35-b62c-541f-baef-2edcf67542b6"}, {"title": "旧五代史·卷八十二", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/jiuwudaishi-082-wu-luan-assignment/source.txt", "note": "《旧五代史》卷八十二，段落 jiu-wudaishi-205deb4a7860-p001997；EPUB电子本，纸本及异文待核", "id": "34660000-c5f0-5693-a56a-17fc940edd9c"}, {"title": "资治通鉴·后晋纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/tongjian-283-944-january-close/source.txt", "note": "《资治通鉴》后晋纪四，段落 zizhi-tongjian-a63549944a71-p003372；电子底本待考，分段待核", "id": "c0e645b4-c629-508d-aba9-c593614a0eba"}, {"title": "新五代史·卷九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/xinwudaishi-009-944-january/source.txt", "note": "《新五代史》卷九，段落 xin-wudaishi-b08f244b9241-p000335；EPUB电子本，纸本及异文待核", "id": "71c7fc99-919d-58e5-acc1-c401819fcdc4"}, {"title": "新五代史·卷二十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/xinwudaishi-029-wu-luan-death/source.txt", "note": "《新五代史》卷二十九，段落 xin-wudaishi-b08f244b9241-p001075；EPUB电子本，纸本及异文待核", "id": "7c283a88-9c9d-5e6c-ad39-cdb78a3a5240"}, {"title": "新五代史·卷62·南唐世家·冯延巳等", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-feng-name/source.txt", "note": "《新五代史》卷62·南唐世家·冯延巳等，段落 xin-wudaishi-b08f244b9241-p003139；已核上下文及传主，纸本及异文待核。", "id": "819d41cd-204a-5095-8cdb-49e78419f252"}, {"title": "资治通鉴·后晋纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4284fc6d71535dbdd9b85d19ca37d8bb9add577/content/books/zizhi-tongjian/vol-283/year-0943/part-05/sources/library/tongjian-283-943-min-liu-zan/source.txt", "note": "《资治通鉴》后晋纪四，段落 zizhi-tongjian-a63549944a71-p003371；电子底本待考，分段待核", "id": "8f986793-33bf-5758-b6d9-8b3d9a744d1b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "赵延照", "aliases": ["趙延照"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思温的儿子。《资治通鉴》记载，他在后晋任祁州刺史，并受父亲委托向石敬瑭转达幽州归附的请求。相关行动的具体年份未载。", "biography": null, "status": "draft", "id": "a3905a7c-cc29-5e76-a63f-eede596759ff"}, {"name": "赵思温", "aliases": ["趙思溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：赵思温，平州人、拒行回应者。", "biography": null, "status": "draft", "id": "6d48dbcb-e174-55d5-895a-98e065e6f82c"}, {"name": "王令温", "aliases": ["王令溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州河间人，后晋永清军节度使。免除邵珂军职，入朝时将其子邵崇范带在身边作人质。贝州陷落后家属被契丹俘获，944年正月被调为邓州节度使。生卒年本批未录。", "biography": null, "status": "draft", "id": "86d0426b-7115-5ca5-8f2c-358de92831a5"}, {"name": "邵珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋永清军军校、王令温牙将，被免职后秘密遣人入契丹，称贝州粮多兵弱。944年正月由吴峦委守南门，随后引契丹入城。生卒年未载。", "biography": null, "status": "draft", "id": "e00acf84-21d4-5743-b1c3-b2acf6b16715"}, {"name": "吴峦", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大同军节度判官。沙彦珣被契丹扣留后，他被推举主持云州事务，并闭城拒守。", "biography": null, "status": "draft", "id": "10e5964b-74c7-5654-afc1-4dfbc96d27c3"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "王周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王周。", "biography": null, "status": "draft", "id": "dcf3a493-1cbc-5185-9787-8041333d1d90"}, {"name": "潘环", "aliases": ["潘環", "潘瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：潘环，王村寨守将、奔梁者。", "biography": null, "status": "draft", "id": "5e093bc1-94d3-542b-ac05-e1f1184aa8ba"}, {"name": "邵崇范", "aliases": ["邵崇範"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "邵珂的儿子。《新五代史》记王令温入朝时，因怀疑邵珂而将邵崇范带在身边作人质。确切年月与生卒年未载。", "biography": null, "status": "draft", "id": "7200aeb2-575e-507e-b653-477b4ba7bbf6"}, {"name": "王令崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王令温的弟弟。《旧五代史》记944年正月戊子从契丹回来，向后晋朝廷说明家族陷在贝州的情况。生卒年未载。", "biography": null, "status": "draft", "id": "020bdd7d-c193-52e7-92da-9c27d8fe122b"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "曹光裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋成德节度使杜重威的幕僚。944年正月前往青州劝说杨光远，又替杨光远入朝奏报并随使者返回慰谕。生卒年未载。", "biography": null, "status": "draft", "id": "59c5fc3c-98f7-5c3e-adea-c007e8d22d57"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "周宗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：周宗。", "biography": null, "status": "draft", "id": "155e76cd-ab0e-5e2a-a791-43d64ebe4669"}, {"name": "张居咏", "aliases": ["張居詠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴国、南唐官员。原任吴国门下侍郎，937年十月与张延翰、李建勋一同被任命为南唐同平章事。", "biography": null, "status": "draft", "id": "64cde81e-02cc-52fd-9160-264f97bd9900"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "萧俨", "aliases": ["蕭儼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，943年开篇记为司门郎中、判大理寺。曾指责陈觉，又反对冯延巳兄弟所草允许卖子女的遗诏，说明李昪先前对此的处理。生卒年尚未核。", "biography": null, "status": "draft", "id": "e8d8e2fc-647f-5c18-8732-94948c94d59a"}, {"name": "贾崇", "aliases": ["賈崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐侍卫都虞候。944年正月条下记其求见李璟，反对限制群臣奏事。自称事奉先帝三十年，此处不据时长倒推出任官年。生卒年未载。", "biography": null, "status": "draft", "id": "94f3a33b-2ca1-5bfd-9b97-4333588ff604"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "王班（后晋殿直）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋殿直，与909年被杀的襄州刺史王班分别建档。944年正月辛巳奉命出使契丹，到邺都无法前进而返回，姓名由《新五代史》补证。生卒年未载。", "biography": null, "status": "draft", "id": "27fec88a-a2ba-5c31-b703-87bc2a3af08c"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "李周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李周。", "biography": null, "status": "draft", "id": "80ce0eab-d01c-5ae2-ad19-5d2e34b7e3b5"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "白承福", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吐谷浑酋长。941年四月辛巳，北京留守李德珫派牙校带领白承福入朝。原文没有说明他是否就是此前归附后晋的某支未具名部众首领。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "404c2172-d65b-534b-aed5-a6e9f5850b6a"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "孟守忠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋译者、译诏官。944年正月奉石重贵命向耶律德光致书，求恢复两国旧好，返回时带回拒绝修好的答复。生卒年未载。", "biography": null, "status": "draft", "id": "4d75b975-8b34-5a38-a22a-ae44417fc06e"}, {"name": "伟王（契丹）", "aliases": ["偉王（契丹）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹王爵称谓，个人姓名在本批史料中未明确。944年正月辛丑，太原奏报在秀容击败其军；《新五代史》记与其交战的晋方将领为刘知远。生卒年未载。", "biography": null, "status": "draft", "id": "c66b0ad9-97a7-5581-809d-b343a2101358"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "颜衎", "aliases": ["顏衎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋枢密直学士、工部郎中。939年废枢密院后，解除院内职务，保留本官。生卒年未载。", "biography": null, "status": "draft", "id": "b9f8cc2c-05c1-565a-a870-6fcd731c4ba9"}, {"name": "窦仪", "aliases": ["竇儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟州人，后晋天平军观察判官。944年正月奉颜衎命向朝廷奏报周儒降契丹、引兵渡河及蔡行遇被俘，并向景延广说明与杨光远会合的危险。生卒年本批未核。", "biography": null, "status": "draft", "id": "9d318328-3904-5714-a390-ea527c3e9fd9"}, {"name": "周儒（后晋博州刺史）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋博州刺史，944年正月投降契丹，并与杨光远通使。颜衎的奏报称其引契丹从马家口渡河，蔡行遇被擒。未证与888年魏博被俘将领周儒同人，分别建档。", "biography": null, "status": "draft", "id": "6c8c96d3-e567-5c7c-bc3b-4486d1d6ba6f"}, {"name": "蔡行遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋均州刺史。941年安从进派其弟安从贵率兵迎击蔡行遇，焦继勋截击安从贵并取胜。生卒年未载。", "biography": null, "status": "draft", "id": "c657ba32-a6f0-5c36-b7f0-d962ecf51cc4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

